from collections import deque, Counter

def comps(mat, value=None, r0=0,r1=None,c0=0,c1=None):
    if r1 is None:r1=len(mat)
    if c1 is None:c1=len(mat[0])
    seen=set(); out=[]
    for r in range(r0,r1):
      for c in range(c0,c1):
        if (r,c) in seen or (value is not None and mat[r][c]!=value): continue
        if value is None and mat[r][c]==mat[0][0]: continue
        val=mat[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
          x,y=q.pop();cells.append((x,y))
          for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
            if r0<=nx<r1 and c0<=ny<c1 and (nx,ny) not in seen and (mat[nx][ny]==val if value is None else mat[nx][ny]==value):
              seen.add((nx,ny));q.append((nx,ny))
        out.append((val,cells))
    return out
