def comp_regions(mat, val_test, r0,r1,c0,c1, diag=4):
  dirs=[(1,0),(-1,0),(0,1),(0,-1)]
  if diag==8: dirs += [(1,1),(1,-1),(-1,1),(-1,-1)]
  seen=set(); out=[]
  for r in range(r0,r1):
    for c in range(c0,c1):
      if (r,c) in seen or not val_test(mat[r][c]):continue
      q=[(r,c)];seen.add((r,c));cells=[]
      while q:
       x,y=q.pop();cells.append((x,y))
       for dx,dy in dirs:
        nx,ny=x+dx,y+dy
        if r0<=nx<r1 and c0<=ny<c1 and (nx,ny) not in seen and val_test(mat[nx][ny]):
         seen.add((nx,ny));q.append((nx,ny))
      out.append(cells)
  return out
